import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { LogOut, User, Bookmark, Home } from 'lucide-react';

const Navbar = () => {
  const { isAuthenticated, user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <nav className="hn-header shadow-lg">
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center space-x-8">
            <Link to="/" className="flex items-center space-x-2 text-white font-bold text-xl">
              <span className="text-2xl">Y</span>
              <span>Hacker News</span>
            </Link>

            <div className="hidden md:flex items-center space-x-6">
              <Link to="/" className="flex items-center space-x-1 text-white hover:text-orange-200 transition-colors">
                <Home size={18} />
                <span>Home</span>
              </Link>

              {isAuthenticated && (
                <Link to="/bookmarks" className="flex items-center space-x-1 text-white hover:text-orange-200 transition-colors">
                  <Bookmark size={18} />
                  <span>Bookmarks</span>
                </Link>
              )}
            </div>
          </div>

          <div className="flex items-center space-x-4">
            {isAuthenticated ? (
              <div className="flex items-center space-x-4">
                <div className="flex items-center space-x-2 text-white">
                  <User size={18} />
                  <span className="hidden md:block">{user?.username}</span>
                </div>
                <button
                  onClick={handleLogout}
                  className="flex items-center space-x-1 text-white hover:text-orange-200 transition-colors"
                >
                  <LogOut size={18} />
                  <span className="hidden md:block">Logout</span>
                </button>
              </div>
            ) : (
              <div className="flex items-center space-x-4">
                <Link
                  to="/login"
                  className="text-white hover:text-orange-200 transition-colors"
                >
                  Login
                </Link>
                <Link
                  to="/register"
                  className="bg-white text-orange-600 px-4 py-2 rounded-md font-medium hover:bg-orange-50 transition-colors"
                >
                  Register
                </Link>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
